Definition default_context_do_init_ossl_s1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra1 u0_1 u1_1 u2_1 b1_1 b2_1 b3_1 b4_1 b5_1 b6_1 b7_1 u3_1 u4_1 u5_1 u6_1 : word) (g1 : byte) (g2 : word) (F1 : bvmap 5 word) (fc1 : bv 32) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms => exists (m' : mem),
    ms = MS (mkR ra sp gp tp u0_1 u1_1 u2_1 s0 s1 (Z_to_bv 64 1) (Z_to_bv 64 12187304) b2_1 b3_1 b4_1 b5_1 b6_1 b7_1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 u3_1 u4_1 u5_1 u6_1)
            F1 (ret_pc ra) fc1 None m' (seg_rom asegs)
    /\ munch [(0xb9f560, 0xb9f561); (0xb9f7a0, 0xb9f7a4); (bv_unsigned sp - 16, bv_unsigned sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' 12187552 [C4 (Z_to_bv 64 1)]
    /\ rw_cells asegs m' 12186976 [C1 (Z_to_bv 8 1)]
    /\ stk asegs m' lo (bv_unsigned sp).

Lemma default_context_do_init_ossl_s1_walk : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra1 u0_1 u1_1 u2_1 b1_1 b2_1 b3_1 b4_1 b5_1 b6_1 b7_1 u3_1 u4_1 u5_1 u6_1 : word) (g1 : byte) (g2 : word) (F1 : bvmap 5 word) (fc1 : bv 32) (m : mem) (lo : Z),
  stk asegs m lo (bv_unsigned sp + -16) -> lo <= (bv_unsigned sp + -16) -> 0x10007fff8000 <= lo -> bv_unsigned sp <= 2 ^ 47 ->
  rw_cells asegs m (bv_unsigned sp + -16) [C8 s0; C8 ra] ->
  rw_cells asegs m 12187552 [C4 g2] ->
  rw_cells asegs m 12186976 [C1 g1] ->
  mem_inv asegs m ->
  evt asegs (default_context_do_init_ossl_s1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra1 u0_1 u1_1 u2_1 b1_1 b2_1 b3_1 b4_1 b5_1 b6_1 b7_1 u3_1 u4_1 u5_1 u6_1 g1 g2 F1 fc1 lo m)
    (MS (mkR ra1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp u0_1 u1_1 u2_1 sp s1 (Z_to_bv 64 1) b1_1 b2_1 b3_1 b4_1 b5_1 b6_1 b7_1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 u3_1 u4_1 u5_1 u6_1)
        F1 (Z_to_bv 64 0x1f7698) fc1 None m (seg_rom asegs)).
Proof.
  intros until lo. intros ST HLO HIMG HTOP FR G2 G1 MI. unfold SEGTOP_A in *.
  pose proof (munch_refl [(0xb9f560, 0xb9f561); (0xb9f7a0, 0xb9f7a4); (bv_unsigned sp - 16, bv_unsigned sp)] m) as MU. pose proof (wmono_refl asegs m) as WM.
  zstep. wg_F.
  do 2 zstep.
  zstore.
  zstep.
  zstore.
  do 4 zstep.
  lazymatch goal with STh : stk _ _ lo _ |- _ => release_frame FR STh (bv_unsigned sp) end.
  unfold default_context_do_init_ossl_s1_post. apply evt_done. do 1 eexists. split; [reflexivity|].
  repeat match goal with |- _ /\ _ => split; [eassumption|] end. eassumption.
Qed.

